 await page.goto('/');const result=await page.evaluate(async()=>{
  const rows=[];
  for(const value of ['  alpha\u00a0beta gamma','  alpha beta gamma','  مرحبا\u00a0بكم هنا  ','  A A  '])for(const direction of ['ltr','rtl'] as const)for(const align of ['left','center','right'] as const){
   const spacing=value.includes('A A')?-45:8,x=align==='left'?200:align==='center'?400:600,c=document.createElement('canvas');c.width=800;c.height=140;const context=c.getContext('2d')!;context.font='normal normal 24px monospace';context.fontKerning='normal';context.letterSpacing='0px';context.wordSpacing=spacing+'px';context.direction=direction;context.textAlign=align;context.textBaseline='alphabetic';context.fillStyle='#2050a0';context.fillText(value,x,60);const expected=context.getImageData(0,0,800,140).data;
   const samples=[];
   for(const kind of ['plain','boundary','nbsp','both','all']){
